async function findGitRoot(startDir: string): Promise<string | null> {
  let currentDir = normalizePath(startDir);
  while (true) {
    const gitPath = path.join(currentDir, '.git');
    try {
      // A `.git` entry (directory for normal repos, file for submodules and
      // worktrees) marks the git root regardless of its type.
      await fs.lstat(gitPath);
      return currentDir;
    } catch (error: unknown) {
      // Don't log ENOENT errors as they're expected when .git doesn't exist.
      // Also don't log errors in test environments, which often have mocked fs.
      const isENOENT =
        typeof error === 'object' &&
        error !== null &&
        'code' in error &&
        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
        (error as { code: string }).code === 'ENOENT';

      const isTestEnv =
        process.env['NODE_ENV'] === 'test' || process.env['VITEST'];

      if (!isENOENT && !isTestEnv) {
        if (typeof error === 'object' && error !== null && 'code' in error) {
          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
          const fsError = error as { code: string; message: string };
          logger.warn(
            `Error checking for .git at ${gitPath}: ${fsError.message}`,
          );
        } else {
          logger.warn(
            `Non-standard error checking for .git at ${gitPath}: ${String(error)}`,
          );
        }
      }
    }
    const parentDir = normalizePath(path.dirname(currentDir));
    if (parentDir === currentDir) {
      return null;
    }
    currentDir = parentDir;
  }
}

